<script setup lang="ts">
import {onMounted,onBeforeUnmount,ref,watch} from 'vue'
import {api,useLoad,useCommand,session,logout,PageHeader,Feedback,EmptyState,StatusBadge,time,type Page} from '@tradeflow/ui'
interface Address {id:string;recipient:string;phone:string;region:string;address:string;defaultAddress:boolean;version:number}
interface Notification {id:string;title:string;content:string;readAt?:string;createdAt:string}
interface Application {id:string;merchantId:string;name:string;description:string;status:string;reason?:string;version:number}
interface Merchant {merchantId:string;name:string;status:string}
const tab=ref('addresses'),notice=ref(''),localError=ref(''),editId=ref(''),deleteTarget=ref<Address|null>(null)
const addressForm=ref({recipient:'',phone:'',region:'',address:'',defaultAddress:false,version:0})
const password=ref({oldPassword:'',newPassword:'',confirm:''}),revokeConfirm=ref(false)
const application=ref({merchantId:'',name:'',description:''}),notificationPage=ref(1),applicationPage=ref(1)
const addresses=useLoad<Address[]>(signal=>api('/users/me/addresses',{signal}))
const notifications=useLoad<Page<Notification>>(signal=>api(`/users/me/notifications?page=${notificationPage.value}&pageSize=10`,{signal}))
const applications=useLoad<Page<Application>>(signal=>api(`/merchant-applications?page=${applicationPage.value}&pageSize=10`,{signal}))
const merchants=useLoad<Merchant[]>(signal=>api('/merchants',{signal}))
const command=useCommand('account'),security=useCommand('account-security')
let generation=0
onBeforeUnmount(()=>{generation++;password.value={oldPassword:'',newPassword:'',confirm:''}})
function resetAddress(){editId.value='';addressForm.value={recipient:'',phone:'',region:'',address:'',defaultAddress:false,version:0}}
function edit(row:Address){generation++;deleteTarget.value=null;editId.value=row.id;addressForm.value={recipient:row.recipient,phone:row.phone,region:row.region||'',address:row.address,defaultAddress:row.defaultAddress,version:row.version};localError.value=''}
/** 每次提交捕获表单和账号代际；迟到响应不能清掉新编辑内容或新账号资料。 */
async function saveAddress(){localError.value='';const body={...addressForm.value},id=editId.value,g=generation
 const result=await command.run('address:'+id,body,key=>api('/users/me/addresses'+(id?'/'+id:''),{method:id?'PUT':'POST',body,key}))
 if(g!==generation||result===undefined)return;await command.reset();if(g!==generation)return;notice.value='地址已保存。';resetAddress();await addresses.reload()
}
async function makeDefault(row:Address){const g=generation,body={recipient:row.recipient,phone:row.phone,region:row.region||'',address:row.address,defaultAddress:true,version:row.version};const result=await command.run('default:'+row.id,body,key=>api('/users/me/addresses/'+row.id,{method:'PUT',body,key}));if(g!==generation||result===undefined)return;await command.reset();if(g===generation){notice.value='默认地址已更新。';await addresses.reload()}}
async function removeAddress(){const row=deleteTarget.value;if(!row)return;const g=generation,result=await command.run('delete:'+row.id,{version:row.version},key=>api(`/users/me/addresses/${row.id}?version=${row.version}`,{method:'DELETE',key}));if(g!==generation||result===undefined)return;await command.reset();if(g===generation){deleteTarget.value=null;resetAddress();notice.value='地址已删除，历史订单地址不受影响。';await addresses.reload()}}
/** 密码只保留于内存和本次请求，不放入命令摘要或持久存储；明确成功后本地同步退出。 */
async function secure(kind:'password'|'revoke'){localError.value='';const g=generation,body={oldPassword:password.value.oldPassword,newPassword:password.value.newPassword}
 if(kind==='password'&&password.value.newPassword!==password.value.confirm){localError.value='两次新密码不一致';return}
 const result=await security.run(kind,{action:kind},key=>api(kind==='password'?'/users/me/password':'/users/me/sessions/revoke-all',{method:'POST',body:kind==='password'?body:undefined,key}))
 if(g!==generation||result===undefined)return;await security.reset();if(g===generation){password.value={oldPassword:'',newPassword:'',confirm:''};logout()}
}
async function markRead(row:Notification){const g=generation,result=await command.run('read:'+row.id,{id:row.id},key=>api('/users/me/notifications/'+row.id+'/read',{method:'POST',key}));if(g!==generation||result===undefined)return;await command.reset();if(g===generation)await notifications.reload()}
async function apply(){localError.value='';if(!/^merchant_[a-z0-9_]{1,48}$/.test(application.value.merchantId)){localError.value='商家编号需以 merchant_ 开头，后接1至48位小写字母、数字或下划线';return}const g=generation,body={...application.value},result=await command.run('apply:'+body.merchantId,body,key=>api('/merchant-applications',{method:'POST',body,key}));if(g!==generation||result===undefined)return;await command.reset();if(g===generation){application.value={merchantId:'',name:'',description:''};notice.value='申请已提交，审核通过后请重新登录进入商家工作台。';applicationPage.value=1;await applications.reload()}}
async function changePage(kind:'notification'|'application',delta:number){generation++;if(kind==='notification'){notificationPage.value+=delta;notifications.clear();await notifications.reload()}else{applicationPage.value+=delta;applications.clear();await applications.reload()}}
function reload(){if(!session.user)return;if(tab.value==='addresses')void addresses.reload();if(tab.value==='notifications')void notifications.reload();if(tab.value==='merchant'){void applications.reload();void merchants.reload()}}
watch(tab,()=>{generation++;notice.value='';localError.value='';password.value={oldPassword:'',newPassword:'',confirm:''};revokeConfirm.value=false;reload()})
watch(()=>session.epoch,()=>{generation++;addresses.clear();notifications.clear();applications.clear();merchants.clear();resetAddress();password.value={oldPassword:'',newPassword:'',confirm:''};application.value={merchantId:'',name:'',description:''};deleteTarget.value=null;notice.value='';localError.value='';notificationPage.value=1;applicationPage.value=1})
onMounted(reload)
</script>

<template><section v-if="session.user"><PageHeader title="我的账号" description="管理收货地址、登录安全、站内通知和商家入驻。"/><nav class="actions account-tabs" aria-label="账号管理"><button v-for="item in [{id:'addresses',label:'收货地址'},{id:'security',label:'登录安全'},{id:'notifications',label:'站内通知'},{id:'merchant',label:'商家入驻'}]" :key="item.id" :class="{primary:tab===item.id}" :aria-pressed="tab===item.id" @click="tab=item.id">{{item.label}}</button></nav>
<p v-if="notice" class="notice" role="status">{{notice}}</p><Feedback :error="localError||command.error.value||security.error.value"/>
<template v-if="tab==='addresses'"><section class="panel"><div class="row spread"><h2>已保存的地址</h2><button :disabled="addresses.loading.value||command.busy.value" @click="addresses.reload()">刷新地址</button></div><Feedback :loading="addresses.loading.value" :error="addresses.error.value"/><EmptyState v-if="addresses.data.value&&!addresses.data.value.length" title="还没有收货地址" description="在下方填写收件信息，便于下次下单。"/><article v-for="row in addresses.data.value" :key="row.id" class="item-line"><h3>{{row.recipient}} · {{row.phone}} <span v-if="row.defaultAddress" class="success-text">默认地址</span></h3><p class="wrap">{{row.region}} {{row.address}}</p><div class="actions"><button :disabled="command.busy.value" @click="edit(row)">编辑</button><button v-if="!row.defaultAddress" :disabled="command.busy.value" @click="makeDefault(row)">设为默认</button><button class="danger-button" :disabled="command.busy.value" @click="deleteTarget=row">删除</button></div></article><div v-if="deleteTarget" class="notice"><p>确认删除 {{deleteTarget.recipient}} 的地址？历史订单不受影响。</p><div class="actions"><button class="danger-button" :disabled="command.busy.value" @click="removeAddress">确认删除</button><button @click="deleteTarget=null">取消</button></div></div></section>
<form class="panel" @submit.prevent="saveAddress"><h2>{{editId?'编辑地址':'新增地址'}}</h2><p v-if="editId" class="muted">当前版本 {{addressForm.version}}，冲突后请刷新并重新编辑。</p><div class="field-grid"><div><label for="recipient">收件人</label><input id="recipient" v-model.trim="addressForm.recipient" required maxlength="64" autocomplete="shipping name"/></div><div><label for="phone">联系电话</label><input id="phone" v-model.trim="addressForm.phone" required maxlength="32" autocomplete="shipping tel" type="tel"/></div></div><label for="address-region">省 / 市 / 区</label><input id="address-region" v-model.trim="addressForm.region" required maxlength="255" autocomplete="shipping address-level1"/><label for="address">详细收货地址</label><textarea id="address" v-model.trim="addressForm.address" required maxlength="500" autocomplete="shipping street-address"/><label class="checkbox-label"><input v-model="addressForm.defaultAddress" type="checkbox"/>设为默认地址</label><div class="actions"><button class="primary" :disabled="command.busy.value" type="submit">{{command.busy.value?'正在保存…':'保存地址'}}</button><button v-if="editId" type="button" @click="generation++;resetAddress()">取消编辑</button></div><p class="small muted">网络结果未确认时，请先刷新列表核对，避免重复新增。</p></form></template>
<template v-if="tab==='security'"><form class="panel" @submit.prevent="secure('password')"><h2>修改登录密码</h2><p class="notice">修改成功后，当前设备和其他设备的旧登录都会失效。</p><label for="old-password">当前密码</label><input id="old-password" v-model="password.oldPassword" type="password" required maxlength="128" autocomplete="current-password"/><label for="new-password">新密码</label><input id="new-password" v-model="password.newPassword" type="password" required minlength="12" maxlength="72" autocomplete="new-password" aria-describedby="password-help"/><p id="password-help" class="small muted">12至72个UTF-8字节，含大小写字母、数字和符号。</p><label for="confirm-password">再次输入新密码</label><input id="confirm-password" v-model="password.confirm" type="password" required maxlength="72" autocomplete="new-password"/><button class="primary full" :disabled="security.busy.value" type="submit">修改密码并退出全部设备</button></form><section class="panel"><h2>退出全部设备</h2><p>撤销当前账号所有已签发的登录令牌，之后需要重新登录。</p><label class="checkbox-label"><input v-model="revokeConfirm" type="checkbox"/>我确认退出全部设备</label><button class="danger-button" :disabled="!revokeConfirm||security.busy.value" @click="secure('revoke')">退出全部设备</button></section></template>
<section v-if="tab==='notifications'" class="panel"><div class="row spread"><h2>站内通知</h2><button :disabled="notifications.loading.value" @click="notifications.reload()">刷新通知</button></div><Feedback :loading="notifications.loading.value" :error="notifications.error.value"/><EmptyState v-if="notifications.data.value&&!notifications.data.value.items.length" title="当前页暂无通知"/><article v-for="row in notifications.data.value?.items" :key="row.id" class="item-line"><h3>{{row.title}}</h3><p class="wrap">{{row.content}}</p><p class="small muted">{{time(row.createdAt)}} · {{row.readAt?'已读':'未读'}}</p><button v-if="!row.readAt" :disabled="command.busy.value" @click="markRead(row)">标记已读</button></article><div v-if="notifications.data.value" class="pagination"><button :disabled="notificationPage<=1||notifications.loading.value" @click="changePage('notification',-1)">上一页</button><span>第 {{notificationPage}} 页 · 共 {{notifications.data.value.total}} 条</span><button :disabled="notificationPage*10>=notifications.data.value.total||notifications.loading.value" @click="changePage('notification',1)">下一页</button></div></section>
<template v-if="tab==='merchant'"><section class="panel"><div class="row spread"><h2>我的商家</h2><button :disabled="merchants.loading.value" @click="merchants.reload()">刷新商家</button></div><Feedback :loading="merchants.loading.value" :error="merchants.error.value"/><EmptyState v-if="merchants.data.value&&!merchants.data.value.length" title="尚无有效商家身份"/><article v-for="merchant in merchants.data.value" :key="merchant.merchantId" class="item-line"><h3>{{merchant.name}}</h3><p class="mono small">{{merchant.merchantId}}</p><p>{{merchant.status==='ACTIVE'?'经营中':'已停用，保留历史处置身份'}}</p></article></section><form class="panel" @submit.prevent="apply"><h2>申请成为商家</h2><label for="merchant-id">商家编号</label><input id="merchant-id" v-model.trim="application.merchantId" required maxlength="57" pattern="merchant_[a-z0-9_]{1,48}" placeholder="例如 merchant_myshop"/><label for="merchant-name">商家名称</label><input id="merchant-name" v-model.trim="application.name" required maxlength="120"/><label for="merchant-description">经营资料</label><textarea id="merchant-description" v-model.trim="application.description" required maxlength="500"/><button class="primary full" :disabled="command.busy.value" type="submit">提交入驻申请</button></form><section class="panel"><div class="row spread"><h2>我的申请</h2><button :disabled="applications.loading.value" @click="applications.reload()">刷新申请</button></div><Feedback :loading="applications.loading.value" :error="applications.error.value"/><EmptyState v-if="applications.data.value&&!applications.data.value.items.length" title="当前页暂无申请"/><article v-for="row in applications.data.value?.items" :key="row.id" class="item-line"><div class="row spread"><h3>{{row.name}}</h3><StatusBadge :status="row.status"/></div><p class="small mono">{{row.merchantId}}</p><p v-if="row.reason" class="wrap">审核原因：{{row.reason}}</p><p v-if="row.status==='APPROVED'" class="notice">审核已通过，请重新登录后进入商家工作台。</p></article><div v-if="applications.data.value" class="pagination"><button :disabled="applicationPage<=1||applications.loading.value" @click="changePage('application',-1)">上一页</button><span>第 {{applicationPage}} 页 · 共 {{applications.data.value.total}} 条</span><button :disabled="applicationPage*10>=applications.data.value.total||applications.loading.value" @click="changePage('application',1)">下一页</button></div></section></template>
</section></template>
<style scoped>.account-tabs{margin-bottom:24px}.account-tabs button{flex:1;min-width:110px}.account-tabs{flex-wrap:wrap}form.panel{max-width:800px}</style>
